def backfill_primary_and_view(apps, schema_editor):
    """Existing photos have no angle/primary info. Per product + color, treat the
    lowest-order photo as the primary front shot and label the rest 'other' so
    nothing is wrongly presented as a back/side/detail view."""
    ProductImage = apps.get_model("catalog", "ProductImage")
    seen = set()
    for img in ProductImage.objects.order_by("product_id", "order", "id").iterator():
        key = (img.product_id, (img.color or "").strip().lower())
        if key in seen:
            ProductImage.objects.filter(pk=img.pk).update(view="other")
        else:
            seen.add(key)
            ProductImage.objects.filter(pk=img.pk).update(is_primary=True, view="front")


